@Component({
  selector: 'app-tarjeta-tarea',
  imports: [DatePipe],
  templateUrl: './tarjeta-tarea.html',
  styleUrl: './tarjeta-tarea.css',
})
export class TarjetaTarea {
  readonly tarea = input.required<Tarea>();
  readonly mover = output<Estado>();
}

@if (cargando()) {
  <p>Cargando…</p>
} @else if (error()) {
  <p>Error: {{ error() }}</p>
} @else {
  <lista-tareas />
}

@for (t of tareas(); track t.id) {
  <app-tarjeta-tarea [tarea]="t" />
} @empty {
  <p>No hay tareas.</p>
}

@switch (tarea().estado) {
  @case ('hecha') { <span>✓</span> }
  @default { <span>…</span> }
}

const tareas = signal<Tarea[]>([]);
const hechas = computed(() => tareas().filter(t => t.estado === 'hecha'));

tareas.set([...]);
tareas.update(lista => [...lista, nueva]);

effect(() => localStorage.setItem('t', JSON.stringify(tareas())));

@Injectable({ providedIn: 'root' })
export class TareasService {
  private readonly http = inject(HttpClient);
  listar() { return this.http.get<Tarea[]>(`${environment.api}/tareas`); }
}

